import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int to, cap, cost, rev;
        public Edge(int to, int cap, int cost, int rev) {
            this.to = to;
            this.cap = cap;
            this.cost = cost;
            this.rev = rev;
        }
    }

    static class MinCostFlow {
        static final int MAX_VERTICES = 5010;
        int V;
        List<Edge>[] G = new ArrayList[MAX_VERTICES];
        int[] h = new int[MAX_VERTICES];
        int[] dist = new int[MAX_VERTICES];
        int[] prevv = new int[MAX_VERTICES];
        int[] preve = new int[MAX_VERTICES];

        public MinCostFlow() {
            for (int i = 0; i < MAX_VERTICES; i++) {
                G[i] = new ArrayList<>();
            }
        }

        void initialize(int n) {
            V = n;
            for (int i = 0; i < V; i++) {
                G[i].clear();
            }
        }

        void addEdge(int from, int to, int cap, int cost) {
            G[from].add(new Edge(to, cap, cost, G[to].size()));
            G[to].add(new Edge(from, 0, -cost, G[from].size() - 1));
        }

        int computeMinCostFlow(int s, int t, int flow) {
            int totalCost = 0;
            Arrays.fill(h, 0);
            while (flow > 0) {
                PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
                Arrays.fill(dist, Integer.MAX_VALUE);
                dist[s] = 0;
                pq.offer(new int[]{0, s});
                while (!pq.isEmpty()) {
                    int[] p = pq.poll();
                    int v = p[1];
                    if (dist[v] < p[0]) continue;
                    for (int i = 0; i < G[v].size(); i++) {
                        Edge e = G[v].get(i);
                        if (e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
                            dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            pq.offer(new int[]{dist[e.to], e.to});
                        }
                    }
                }
                if (dist[t] == Integer.MAX_VALUE) {
                    return -1;
                }
                for (int v = 0; v < V; v++) h[v] += dist[v];
                int d = flow;
                for (int v = t; v != s; v = prevv[v]) {
                    d = Math.min(d, G[prevv[v]].get(preve[v]).cap);
                }
                flow -= d;
                totalCost += d * h[t];
                for (int v = t; v != s; v = prevv[v]) {
                    Edge e = G[prevv[v]].get(preve[v]);
                    e.cap -= d;
                    G[v].get(e.rev).cap += d;
                }
            }
            return totalCost;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int[] a = new int[50];
        int[] countArr = new int[50];
        List<Integer>[] adj = new ArrayList[50];
        for (int i = 0; i < 50; i++) {
            adj[i] = new ArrayList<>();
        }

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            a[i] = Integer.parseInt(st.nextToken());
            countArr[a[i] - 1]++;
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken()) - 1;
            int y = Integer.parseInt(st.nextToken()) - 1;
            adj[x].add(y);
            adj[y].add(x);
        }

        int T = 100;
        MinCostFlow minCostFlowSolver = new MinCostFlow();
        int totalVertices = n * T + 2;
        minCostFlowSolver.initialize(totalVertices);

        int source = n * T;
        int sink = n * T + 1;

        for (int i = 0; i < n; i++) {
            minCostFlowSolver.addEdge(source, i, countArr[i], 0);
        }

        for (int i = 0; i < T; i++) {
            minCostFlowSolver.addEdge(i * n, sink, k, c * i);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < T - 1; j++) {
                minCostFlowSolver.addEdge(j * n + i, (j + 1) * n + i, k, 0);
            }
            for (int to : adj[i]) {
                for (int j = 0; j < T - 1; j++) {
                    for (int u = 0; u < k; u++) {
                        int cost = (u + 1) * (u + 1) * d - u * u * d;
                        minCostFlowSolver.addEdge(j * n + i, (j + 1) * n + to, 1, cost);
                    }
                }
            }
        }

        System.out.println(minCostFlowSolver.computeMinCostFlow(source, sink, k));
    }
}
